  "cabeca": "<h1 class=\"mapa-titulo\">Mapa de Risco de <span class=\"grad-tx\">§NOME§</span></h1><p class=\"mapa-data\"><svg class=\"ic \" aria-hidden=\"true\"><use href=\"#i-calendario\"/></svg>§DATA§</p>",
  "cta": "<section class=\"cta bl\"><svg class=\"cta__raios\" viewBox=\"0 0 220 220\" aria-hidden=\"true\"><line x1=\"156.0\" y1=\"110.0\" x2=\"214.0\" y2=\"110.0\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\"/><line x1=\"154.4\" y1=\"121.9\" x2=\"193.1\" y2=\"132.3\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\"/><line x1=\"149.8\" y1=\"133.0\" x2=\"200.1\" y2=\"162.0\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\"/><line x1=\"142.5\" y1=\"142.5\" x2=\"170.8\" y2=\"170.8\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\"/><line x1=\"133.0\" y1=\"149.8\" x2=\"162.0\" y2=\"200.1\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\"/><line x1=\"121.9\" y1=\"154.4\" x2=\"132.3\" y2=\"193.1\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\"/><line x1=\"110.0\" y1=\"156.0\" x2=\"110.0\" y2=\"214.0\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\"/><line x1=\"98.1\" y1=\"154.4\" x2=\"87.7\" y2=\"193.1\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\"/><line x1=\"87.0\" y1=\"149.8\" x2=\"58.0\" y2=\"200.1\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\"/><line x1=\"77.5\" y1=\"142.5\" x2=\"49.2\" y2=\"170.8\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\"/><line x1=\"70.2\" y1=\"133.0\" x2=\"19.9\" y2=\"162.0\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\"/><line x1=\"65.6\" y1=\"121.9\" x2=\"26.9\" y2=\"132.3\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\"/><line x1=\"64.0\" y1=\"110.0\" x2=\"6.0\" y2=\"110.0\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\"/><line x1=\"65.6\" y1=\"98.1\" x2=\"26.9\" y2=\"87.7\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\"/><line x1=\"70.2\" y1=\"87.0\" x2=\"19.9\" y2=\"58.0\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\"/><line x1=\"77.5\" y1=\"77.5\" x2=\"49.2\" y2=\"49.2\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\"/><line x1=\"87.0\" y1=\"70.2\" x2=\"58.0\" y2=\"19.9\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\"/><line x1=\"98.1\" y1=\"65.6\" x2=\"87.7\" y2=\"26.9\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\"/><line x1=\"110.0\" y1=\"64.0\" x2=\"110.0\" y2=\"6.0\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\"/><line x1=\"121.9\" y1=\"65.6\" x2=\"132.3\" y2=\"26.9\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\"/><line x1=\"133.0\" y1=\"70.2\" x2=\"162.0\" y2=\"19.9\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\"/><line x1=\"142.5\" y1=\"77.5\" x2=\"170.8\" y2=\"49.2\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\"/><line x1=\"149.8\" y1=\"87.0\" x2=\"200.1\" y2=\"58.0\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\"/><line x1=\"154.4\" y1=\"98.1\" x2=\"193.1\" y2=\"87.7\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"110\" cy=\"110\" r=\"26\" fill=\"none\" stroke=\"#fff\" stroke-width=\"3\"/></svg><p class=\"cta__texto\">O mapa aponta onde investigar. A consulta confirma, com exames, e trata.</p><a class=\"btn btn--branco\" href=\"https://pay.hub.la/xsvWVGbmQbri6iXyzlDb\"><svg class=\"ic \" aria-hidden=\"true\"><use href=\"#i-agendar\"/></svg>Agendar minha consulta</a></section>",
  "barra": "<div class=\"barra-cta\" hidden><a class=\"btn btn--primario\" href=\"https://pay.hub.la/xsvWVGbmQbri6iXyzlDb\"><svg class=\"ic \" aria-hidden=\"true\"><use href=\"#i-agendar\"/></svg>Agendar minha consulta</a></div>",
  "remedios": "<article class=\"bloco bl\"><div class=\"bloco__cab\"><span class=\"bloco__ic\"><svg class=\"ic \" aria-hidden=\"true\"><use href=\"#i-pilula\"/></svg></span><h2 class=\"bloco__titulo\">Remédios que podem estar interferindo</h2></div><div class=\"chips\">§CHIPS§</div><p class=\"bloco__texto\">Alguns remé­dios de uso con­tí­nuo <strong class=\"dq\">podem derrubar a ereção</strong>. <strong class=\"dq\">Nunca pare por conta própria</strong>: o médico ajusta sem você largar o tra­ta­mento.</p></article>",
  "chip": "<span class=\"chip\"><svg class=\"ic \" aria-hidden=\"true\"><use href=\"#i-pilula\"/></svg>§CHIP§</span>",
  "tentou": {
   "azulzinho": "<article class=\"bloco bl\"><div class=\"bloco__cab\"><span class=\"bloco__ic\"><svg class=\"ic \" aria-hidden=\"true\"><use href=\"#i-historico\"/></svg></span><h2 class=\"bloco__titulo\">Sobre o que você já tentou</h2></div><div class=\"chips\"><span class=\"chip\">Azulzinho ou parecido</span></div><p class=\"bloco__texto\">O azul­zi­nho abre o fluxo por <strong class=\"dq\">algumas horas</strong> e <strong class=\"dq\">não trata nenhum dos 4 pilares</strong>. Por isso ele falha, e você falha junto.</p></article>",
   "nunca": "<article class=\"bloco bl\"><div class=\"bloco__cab\"><span class=\"bloco__ic\"><svg class=\"ic \" aria-hidden=\"true\"><use href=\"#i-historico\"/></svg></span><h2 class=\"bloco__titulo\">Sobre o que você já tentou</h2></div><div class=\"chips\"><span class=\"chip\">Nunca tentei</span></div><p class=\"bloco__texto\">Você nunca inves­ti­gou. Esse mapa é o <strong class=\"dq\">primeiro passo</strong>.</p></article>"
  },
  "legal": "Mapa indicativo, baseado nas suas respostas. Não substitui consulta médica.<br>AndroClinic, Dr.&nbsp;Cristiano Estivalet, CRM&#8209;DF&nbsp;15471.",
